"""The Pi vectors of pi-ai's ``Type`` (test/parity/sdk-vectors/pi-ai/Type.json, generated by automation/gen/generate-sdk-vectors.mjs): what TypeBox 1.3.27's own constructors
and guards return, as the JSON text (so key order and number text are compared), the hidden members and the guards' booleans. Every case is run."""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

import pytest

from pig_sdk import TSchema, TSchemaArray, Type

VECTORS = Path(__file__).resolve().parents[3] / "test" / "parity" / "sdk-vectors" / "pi-ai" / "Type.json"


def _snake(name: str) -> str:
    if name == "With":
        return "with_"
    return re.sub(r"(?<!^)(?=[A-Z])", "_", name).lower()


def _predicate(spec: dict):
    """The predicate or message function a case names (the generator's predicateFor builds the same from the same spec)."""
    name = spec["$fn"]
    if name == "always":
        return lambda value: True
    if name == "never":
        return lambda value: False
    if name == "lengthAtLeast":
        return lambda value: len(str(value)) >= spec["n"]
    if name == "equals":
        return lambda value: value == spec["value"]
    if name == "even":
        return lambda value: value % 2 == 0
    if name == "greaterThan":
        return lambda value: value > spec["n"]
    if name in ("throws", "throwsText", "errorThrows"):
        def raises(value):
            raise RuntimeError(spec["message"])
        return raises
    if name == "text":
        return lambda value: spec["text"]
    if name == "textWithValue":
        return lambda value: spec["prefix"] + str(value)
    raise AssertionError(f"no predicate {name}")


def _resolve(node: Any) -> Any:
    if isinstance(node, list):
        return [_resolve(item) for item in node]
    if isinstance(node, dict):
        if isinstance(node.get("$fn"), str):
            return _predicate(node)
        if isinstance(node.get("$call"), str):
            return getattr(Type, _snake(node["$call"]))(*[_resolve(arg) for arg in node["args"]])
        return {key: _resolve(value) for key, value in node.items()}
    return node


def _cases() -> list[dict]:
    cases = json.loads(VECTORS.read_text(encoding="utf-8"))["cases"]
    assert cases, "Type.json has no cases"
    return cases


@pytest.mark.parametrize("case", _cases(), ids=lambda case: case["name"])
def test_type_matches_pi(case):
    if "throws" in case:
        with pytest.raises(Exception) as raised:
            _resolve(case["args"][0])
        assert str(raised.value) == case["throws"]
        return
    got = _resolve(case["args"][0])
    want = case["result"]
    if isinstance(got, (TSchema, TSchemaArray)):
        assert isinstance(want, dict) and "json" in want, f"the SDK answers a schema, Pi {want}"
        assert got.to_json() == want["json"]
        hidden = {key: ({"count": len(value)} if key == "~refine" else value) for key, value in got.hidden.items()}
        assert hidden == want["hidden"]
    else:
        assert got == want
        assert type(got) is type(want)


def test_type_omits_the_codec_family():
    """The evidence of divergence D198: the Codec family of Pi's Type is not served, so none of its members exists."""
    for name in ("codec", "decode", "encode", "decode_builder", "encode_builder", "is_codec"):
        assert not hasattr(Type, name), f"Type.{name} exists; D198 records that the Codec family is not served"
